css:
[data-bz-section="location-summary"] .bz-block { padding-block: 0 }
[data-bz-section="location-summary"] .bz-block + .bz-block { padding-block-start: 0 }
/* Handoff .split: 1.5fr / 1fr with a 48px gutter, both columns top-aligned; stacks at 1100px. */
@media (min-width: 1101px) {
  [data-bz-section="location-summary"] [data-bz-node="ls-row"] { grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); gap: 48px; align-items: start }
  [data-bz-section="location-summary"] [data-bz-node="ls-row"] > .bz-col { grid-column: auto }
}
@media (max-width: 1100px) { [data-bz-section="location-summary"] [data-bz-node="ls-row"] { gap: 40px } }
[data-bz-section="location-summary"] [data-bz-node^="ls-id"] { margin: 0 }
/* The heading is the business the branch trades as (Admin → Locations → the rooftop's trading name),
   and the branch name when that is not filled in: the name heading only shows while the first is empty. */
[data-bz-section="location-summary"] [data-bz-node^="ls-h-"]:has(h2) + [data-bz-node^="ls-name-"] { display: none }
[data-bz-section="location-summary"] [data-bz-node^="ls-name-"] h2 { margin-top: 0 }
[data-bz-section="location-summary"] h2 { font-size: 30px; line-height: 1.7; font-weight: 800; margin: 0 0 18px }
/* The eyebrow can be the heading block's only line (no trading name yet), where the base :last-child rule would drop its margin. */
[data-bz-section="location-summary"] [data-bz-node^="ls-h-"] p.bz-eyebrow { margin-bottom: 18px }
[data-bz-section="location-summary"] [data-bz-node^="ls-addr"] p { font-size: 16px; line-height: 1.75; color: var(--body-text); margin: 0 0 22px }
/* Handoff .phone-list: hairline-ruled rows, a 128px tracked label column and the number beside it. */
[data-bz-section="location-summary"] [data-bz-node="ls-phones"] .bz-phones { gap: 8px; margin: 0 0 22px; padding: 0; list-style: none }
[data-bz-section="location-summary"] [data-bz-node="ls-phones"] .bz-phone { display: flex; justify-content: flex-start; align-items: baseline; flex-wrap: wrap; gap: 12px; border-top: 1px solid var(--line); border-bottom: 0; padding: 12px 0 0; font-size: 16px; line-height: 1.7 }
[data-bz-section="location-summary"] [data-bz-node="ls-phones"] .bz-phone__l { font: 700 10px / 1.4 var(--font-body); letter-spacing: .12em; text-transform: uppercase; color: var(--muted); min-width: 128px }
[data-bz-section="location-summary"] [data-bz-node="ls-phones"] .bz-phone a, [data-bz-section="location-summary"] [data-bz-node="ls-phones"] .bz-phone > span + span { font-size: 15px; font-weight: 700; line-height: 1.7; color: var(--ink); text-decoration: none }
[data-bz-section="location-summary"] [data-bz-node="ls-phones"] .bz-phone a:hover { text-decoration: underline }
/* Handoff .notice: a dark inset block, 26px in. */
[data-bz-section="location-summary"] [data-bz-node="ls-notice"] { background: var(--ink); color: #fff; padding: 26px; margin: 0 }
[data-bz-section="location-summary"] [data-bz-node="ls-notice"] .bz-eyebrow { font-size: 10px; line-height: 1.3; letter-spacing: .14em; color: var(--accent-dark); margin: 0 0 18px }
[data-bz-section="location-summary"] [data-bz-node="ls-notice"] h3 { font-size: 20px; line-height: 1.7; font-weight: 800; color: #fff; margin: 0 0 12px }
[data-bz-section="location-summary"] [data-bz-node="ls-notice-b"] p { font-size: 15px; line-height: 1.7; color: var(--chrome-body); margin: 0 0 14px }
[data-bz-section="location-summary"] [data-bz-node="ls-notice-cta"] .bz-btns { margin-block: 0 }
[data-bz-section="location-summary"] [data-bz-node="ls-notice-cta"] .bz-btn--link { font: 700 16px / 1.7 var(--font-body); color: #fff; text-transform: none; letter-spacing: 0 }
/* Handoff .map: a fixed-height framed box beside the contact block. It holds the branch's own photo from
   Admin → Locations; a branch with none yet shows the empty frame, which says "upload one". */
[data-bz-section="location-summary"] [data-bz-node="ls-map-w"] .bz-locphoto { position: relative; height: 520px; border: 1px solid var(--line); background: var(--paper); overflow: hidden; border-radius: 0 }
[data-bz-section="location-summary"] [data-bz-node="ls-map-w"] .bz-locphoto img { display: block; width: 100%; height: 100%; object-fit: cover }
[data-bz-section="location-summary"] [data-bz-node="ls-map-w"] .bz-locphoto__empty { height: 100%; aspect-ratio: auto; border: 0; border-radius: 0; background: none }
@media (max-width: 640px) {
  [data-bz-section="location-summary"] h2 { font-size: 26px }
  [data-bz-section="location-summary"] [data-bz-node="ls-map-w"] .bz-locphoto { height: 320px }
  [data-bz-section="location-summary"] [data-bz-node="ls-notice"] .bz-eyebrow { font-size: 12px }
}
